def operation(n):
    if n < 0:
        return n
    if n == 0:
        return 0
    d = n % 10
    m = n // 10
    return m + 3 * d

# Test starting values up to 50 to find behavior
test_starts = range(1, 51)
results = {}

for start in test_starts:
    sequence = [start]
    history = {start}
    n = start

    # Simulate up to 100 steps or until a cycle/fixed point is found
    for _ in range(100):
        n_next = operation(n)

        if n_next == 0:
            break
        if n_next in history:
            # Cycle detected
            results[start] = f"Cycle detected starting at {n_next}: {sequence[sequence.index(n_next):]}"
            break

        sequence.append(n_next)
        history.add(n_next)
        n = n_next
    else:
        # Did not cycle within 100 steps (unlikely for this function, but safe)
        results[start] = f"No cycle found after 100 steps (ends at {n})"

# Print the results for inspection
for start, result in sorted(results.items()):
    print(f"{start}: {result}")
